package org.example.skillsprint.controller;

import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import jakarta.servlet.http.HttpSession;
import org.example.skillsprint.dao.CertificateDAO;import org.example.skillsprint.model.Certificate;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
import java.io.IOException;import java.net.URI;import java.sql.Date;import java.sql.SQLException;import java.time.LocalDate;import java.time.format.DateTimeParseException;

@Controller @RequestMapping("/certificates")
public class CertificateController {
    private final CertificateDAO dao;public CertificateController(CertificateDAO dao){this.dao=dao;}
    @GetMapping({"","/","/list"}) public String list(Model m,HttpServletRequest req,HttpServletResponse res){try{m.addAttribute("certificates",dao.listForUser(uid(req)));return "certificate-list";}catch(SQLException e){return error(m,res);}}
    @GetMapping("/new") public String newForm(Model m){return form(m,new Certificate(),false,null,null);}
    @GetMapping("/edit") public String edit(@RequestParam("id") String id,Model m,HttpServletRequest req,HttpServletResponse res) throws IOException {Integer i=parse(id);if(i==null){res.sendError(400,"Invalid certificate ID.");return null;}try{Certificate c=dao.findForUser(i,uid(req));if(c==null){res.sendError(404,"Certificate not found.");return null;}return form(m,c,true,null,null);}catch(SQLException e){return error(m,res);}}
    @PostMapping("/create") public String create(@RequestParam(name="title",defaultValue="") String title,@RequestParam(name="issuer",defaultValue="") String issuer,@RequestParam(name="issueDate",required=false) String issueDate,@RequestParam(name="credentialLink",defaultValue="") String credentialLink,Model m,HttpServletRequest req,HttpServletResponse res) throws IOException {return save(0,false,title,issuer,issueDate,credentialLink,m,req,res);}
    @PostMapping("/update") public String update(@RequestParam("id") String id,@RequestParam(name="title",defaultValue="") String title,@RequestParam(name="issuer",defaultValue="") String issuer,@RequestParam(name="issueDate",required=false) String issueDate,@RequestParam(name="credentialLink",defaultValue="") String credentialLink,Model m,HttpServletRequest req,HttpServletResponse res) throws IOException {Integer i=parse(id);if(i==null){res.sendError(400,"Invalid certificate ID.");return null;}return save(i,true,title,issuer,issueDate,credentialLink,m,req,res);}
    @PostMapping("/delete") public String delete(@RequestParam("id") String id,Model m,HttpServletRequest req,HttpServletResponse res) throws IOException {Integer i=parse(id);if(i==null){res.sendError(400,"Invalid certificate ID.");return null;}try{if(!dao.delete(i,uid(req))){res.sendError(404,"Certificate not found.");return null;}return "redirect:/certificates/list";}catch(SQLException e){return error(m,res);}}
    private String save(int id,boolean edit,String title,String issuer,String raw,String link,Model m,HttpServletRequest req,HttpServletResponse res) throws IOException {int user=uid(req);Certificate c=new Certificate();c.setCertificateId(id);c.setUserId(user);c.setTitle(title.trim());c.setIssuer(issuer.trim());c.setCredentialLink(link.trim());String d=trim(raw);if(!d.isEmpty())try{c.setIssueDate(Date.valueOf(LocalDate.parse(d)));}catch(DateTimeParseException ignored){}
        String e=validate(c,raw);if(e!=null)return form(m,c,edit,e,raw);try{if(edit){if(!dao.update(c,user)){res.sendError(404,"Certificate not found.");return null;}}else dao.create(c);return "redirect:/certificates/list";}catch(SQLException ex){return error(m,res);}}
    private String validate(Certificate c,String raw){if(c.getTitle().isEmpty())return "Certificate title is required.";if(c.getTitle().length()>150)return "Certificate title must be 150 characters or fewer.";if(len(c.getIssuer())>100)return "Issuer must be 100 characters or fewer.";if(len(c.getCredentialLink())>500)return "Credential URL must be 500 characters or fewer.";if(raw!=null&&!raw.trim().isEmpty()&&c.getIssueDate()==null)return "Enter a valid issue date.";if(!c.getCredentialLink().isEmpty()&&!url(c.getCredentialLink()))return "Credential URL must be a valid HTTP or HTTPS URL.";return null;}
    private boolean url(String s){try{URI u=new URI(s);return u.getScheme()!=null&&(u.getScheme().equalsIgnoreCase("http")||u.getScheme().equalsIgnoreCase("https"))&&u.getHost()!=null&&!u.getHost().isEmpty();}catch(Exception e){return false;}}
    private String form(Model m,Certificate c,boolean edit,String error,String raw){m.addAttribute("certificate",c);m.addAttribute("editMode",edit);m.addAttribute("error",error);m.addAttribute("rawDate",raw);return "certificate-form";}
    private String error(Model m,HttpServletResponse r){r.setStatus(500);m.addAttribute("error","The certificate could not be saved or loaded. Please try again.");return "certificate-error";}
    private int uid(HttpServletRequest r){HttpSession s=r.getSession(false);Object v=s==null?null:s.getAttribute("userId");return v instanceof Number?((Number)v).intValue():0;}
    private Integer parse(String s){try{return s!=null&&s.matches("[1-9][0-9]{0,9}")?Integer.valueOf(s):null;}catch(NumberFormatException e){return null;}}
    private String trim(String s){return s==null?"":s.trim();}private int len(String s){return s==null?0:s.length();}
}
